<?php declare(strict_types=1); $e=static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, "UTF-8"); ?><style>.cr-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cr-stat{padding:22px;border-radius:14px}.cr-stat .n{font-size:30px;font-weight:700}.cr-muted{color:#667085}.cr-actions{display:flex;gap:8px;flex-wrap:wrap}.cr-badge{display:inline-block;padding:5px 9px;border-radius:999px;font-size:12px;background:#eef2f6}@media(max-width:900px){.cr-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr!important}}</style><div class="page-header"><div><h1>Vehicle Categories</h1><p>Categories such as Pickup, Truck, Tractor, JCB and Water Tanker.</p></div><div class="page-actions"><a class="btn btn-primary" href="<?= config('app.base_path') ?>/commercial-rentals/categories/create">Add Category</a></div></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Slug</th><th>Description</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(empty($categories)): ?><tr><td colspan="5"><div class="empty-state">No categories found.</div></td></tr><?php else: foreach($categories as $row): ?><tr><td><?= $e($row['name']) ?></td><td><code><?= $e($row['slug']) ?></code></td><td><?= $e($row['description'] ?? '—') ?></td><td><?= $e($row['status']) ?></td><td><a class="link-button" href="<?= config('app.base_path') ?>/commercial-rentals/categories/<?= (int)$row['id'] ?>/edit">Edit</a></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
